import{B,C,read,circle,ray,path}from'../ten-utils.js';import{fmt10}from'../ten-math.js';
export default({g,p,extra})=>{let m=extra.mode??0,k=p[0];if(m===2){path(g,[[-.3,-.7,0],[-.7,.6,0],[.65,.6,0],[-.3,-.7,0]],C.white,3);ray(g,[-1.5,-.1,0],[-.5,-.1,0],C.white);let colors=['#f28d8d','#f1a277',C.gold,C.green,C.blue,'#d8a9ff'];colors.forEach((c,i)=>ray(g,[-.1,0,0],[1.3,.08+i*.12,0],c));return[read('Wavelength','तरंगदैर्घ्य',k,'nm'),read('Relative scattering: (700 / λ)^4','सापेक्ष प्रकीर्णन: (700 / λ)^4',fmt10((700/k)**4)),read('Model distinction','मॉडल का अंतर',B('Prism dispersion separates wavelengths; scattering is a separate phenomenon','प्रिज्म में वर्ण विक्षेपण तरंगदैर्घ्यों को अलग करता है; प्रकीर्णन अलग घटना है'))]}
circle(g,.25,0,.8,C.white);g.line([.8,-.6,0],[.8,.6,0],C.pink,4);g.line([-.3,-.4,0],[-.3,.4,0],C.blue,5);if(m===0){let f=2*k/(k+2),ox=-.95-.5*(k-25)/175,ih=.5*25/k,w=.04+.12*(200-k)/175;for(let sign of[-1,1])path(g,Array.from({length:21},(_,i)=>{let y=(i-10)*.04;return[-.3+sign*w*(1-y*y/.16),y,0]}),C.blue,2);g.arrow([ox,0,0],[ox,-.65,0],C.green);g.arrow([.8,0,0],[.8,ih,0],C.pink);for(let y of[-.25,.25]){ray(g,[ox,-.65,0],[-.3,y,0]);ray(g,[-.3,y,0],[.8,ih,0])}return[read('Object distance','वस्तु दूरी',k,'cm'),read('Illustrative focal length','सांकेतिक फोकस दूरी',fmt10(f,3),'cm'),read('Illustrative lens power','सांकेतिक लेंस क्षमता',fmt10(100/f),'D')]}
g.line([-.8,-.5,0],[-.8,.5,0],C.green,3);let focus=.45+.35*(-k/2);for(let y of[-.3,.3]){ray(g,[-1.5,y,0],[-.3,y,0]);ray(g,[-.3,y,0],[Math.min(1.5,focus),0,0])}return[read('Correcting lens power','सुधारक लेंस की क्षमता',k,'D'),read('For a 50 cm far point','50 cm दूर बिंदु के लिए',Math.abs(k+2)<.01?B('Correct: −2 D diverging lens brings distant-object image to far point','सही: −2 D अपसारी लेंस दूर वस्तु का प्रतिबिंब दूर बिंदु पर बनाता है'):B('Adjust towards −2 D for this myopic eye','इस निकटदृष्टि आँख के लिए −2 D तक समायोजित करें'))]};
